	case bool:
		field.Set("type", av.Int("BOOLEAN"))
	case string:
		field.Set("type", av.String("STRING"))
	default:
		panic("Unknown data type")
	}
	sb.schema.Merge(field)
}

// build final Avro schema
func (sb *SchemaBuilder) Build() (*av.Schema, error) {
	return sb.schema.Clone(), nil
}

