```matlab
% Initialize populations with different traits
populationSize = 100;
traitA = randn(populationSize, 1); % Normal distribution with mean 0 and standard deviation 1
traitB = 0.5 * randn(populationSize, 1) + 1; % Normal distribution with mean 1 and standard deviation 0.5

% Define fitness function based on trait value
fitnessFunction = @(x) x^2;

% Calculate fitness scores for each population
fitnessScoreA = fitnessFunction(traitA);
fitnessScoreB = fitnessFunction(traitB);

% Select individuals based on fitness score
survivorsA = sort(traitA, 'descend')(1:round(0.9 * populationSize));
survivorsB = sort(traitB, 'descend')(1:round(0.9 * populationSize));

% Reproduce survivors and pass on traits to offspring
offspringA = survivorsA .* [0.9 0.1];
offspringB = survivorsB .* [0.9 0.1];
newPopulationA = [offspringA(:, 1), offspringB(:, 1)];
newPopulationB = [offspringA(:, 2), offspringB(:, 2)];

% Repeat simulation over multiple generations
for generation = 2:100
    % Update trait values
    traitA = newPopulationA(1:generation-1, :) + 0.01 * randn(generation-1, 1);
    traitB = newPopulationB(1:generation-1, :) + 0.01 * randn(generation-1, 1);
    % Calculate fitness scores
    fitnessScoreA = fitnessFunction(traitA);
    fitnessScoreB = fitnessFunction(traitB);
    % Select survivors and reproduce
    survivorsA = sort(traitA, 'descend')(1:round(0.9 * populationSize));
    survivorsB = sort(traitB, 'descend')(1:round(0.9 * populationSize));

