To open and close the camera and microphone using the MediaDevices API, follow these steps:

a. Opening Camera:

```javascript
async function openCamera() {
  const stream = await navigator.mediaDevices.getUserMedia({ video: true });
  videoElement.srcObject = stream;
}

// Close camera
function closeCamera() {
  videoElement.srcObject.getTracks().forEach(track => track.stop());
}
```

b. Opening Microphone:

```javascript
async function openMicrophone() {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  audioContext.createMediaStreamSource(stream).connect(audioDestination);
}

// Close microphone
function closeMicrophone() {
  audioContext.stop();
}
```

2. Using the WebRTC API:

To open and close the camera and microphone using the WebRTC API, follow these steps:

a. Opening Camera:

```javascript
async function openCameraWebRTC() {
  const localStream = await navigator.mediaDevices.getUserMedia({ video: true });
  localVideoElement.srcObject = localStream;
}

// Close camera
function closeCameraWebRTC() {
  localVideoElement.srcObject.getTracks().forEach(track => track.stop());
}
```

b. Opening Microphone:

```javascript
async function openMicrophoneWebRTC() {
  const localStream = await navigator.mediaDevices.getUserMedia({ audio: true });
  audioContextWebRTC.createMediaStreamSource(localStream).connect(audioDestinationWebRTC);
}

// Close microphone
function closeMicrophoneWebRTC() {
  audioContextWebRTC.close();
}
```

Note: In this method, we create separate `AudioContext` and `MediaStreamSource` objects for the WebRTC case.

