    let gratitudeExpression = "I'm grateful for"

    // Combining all the elements
    return "Life is worth living with \(newPhrase)\n\(gratitudeExpression) \(randomWord.prefix(3)).\n\(randomWord) \(newPhrase)! "
}
```

