    const url = api.checkPortInStatus(this.user.getProductCode(), mnpPhoneNo);
    axios
      .get(url, {
        headers: { Authorization: `Bearer ${this.user.getAccessToken()}`, },
      })
      .then((response) => {
        let updatedRegistrations = [...this.state.registrations];
        const index = updatedRegistrations.findIndex((item) => item.registrationID === registrationId);
        updatedRegistrations[index].mnpStatus = response.data.status;
        this.setState({ registrations: updatedRegistrations });
